describe('Customer Registration Form', () => {
  it('should allow user to register successfully with valid inputs', () => {
    cy.visit('https://parabank.parasoft.com/parabank/register.htm');
    cy.get('input[name="customer.firstName"]').type('John');
    cy.get('input[name="customer.lastName"]').type('Doe');
    cy.get('input[name="customer.address.street"]').type('123 Main St');
    cy.get('input[name="customer.address.city"]').type('Anytown');
    cy.get('input[name="customer.address.state"]').type('CA');
    cy.get('input[name="customer.address.zipCode"]').type('12345');
    cy.get('input[name="customer.phoneNumber"]').type('555-555-5555');
    cy.get('input[name="customer.ssn"]').type('123-45-6789');
    cy.get('input[name="customer.username"]').type('johndoe');
    cy.get('input[name="customer.password"]').type('Password1');
    cy.get('input[name="repeatedPassword"]').type('Password1');
    cy.get('input[value="Register"]').click();
    cy.url().should('not.eq', 'https://parabank.parasoft.com/parabank/register.htm');
  });

  it('should not allow submission with empty required fields', () => {
    cy.visit('https://parabank.parasoft.com/parabank/register.htm');
    cy.get('input[value="Register"]').click();
    cy.url().should('eq', 'https://parabank.parasoft.com/parabank/register.htm');
    cy.get('input[name="customer.firstName"]').should('be.visible');
    cy.get('input[name="customer.lastName"]').should('be.visible');
    cy.get('input[name="customer.address.street"]').should('be.visible');
    cy.get('input[name="customer.address.city"]').should('be.visible');
    cy.get('input[name="customer.address.state"]').should('be.visible');
    cy.get('input[name="customer.address.zipCode"]').should('be.visible');
    cy.get('input[name="customer.phoneNumber"]').should('be.visible');
    cy.get('input[name="customer.ssn"]').should('be.visible');
    cy.get('input[name="customer.username"]').should('be.visible');
    cy.get('input[name="customer.password"]').should('be.visible');
    cy.get('input[name="repeatedPassword"]').should('be.visible');
  });
});

