import { test, expect } from '@playwright/test';

test.describe('Customer Registration Form', () => {
  test('should allow user to register successfully with valid inputs', async ({ page }) => {
    await page.goto('https://parabank.parasoft.com/parabank/register.htm');
    await page.fill('input[name="customer.firstName"]', 'John');
    await page.fill('input[name="customer.lastName"]', 'Doe');
    await page.fill('input[name="customer.address.street"]', '123 Main St');
    await page.fill('input[name="customer.address.city"]', 'Anytown');
    await page.fill('input[name="customer.address.state"]', 'CA');
    await page.fill('input[name="customer.address.zipCode"]', '12345');
    await page.fill('input[name="customer.phoneNumber"]', '555-555-5555');
    await page.fill('input[name="customer.ssn"]', '123-45-6789');
    await page.fill('input[name="customer.username"]', 'johndoe');
    await page.fill('input[name="customer.password"]', 'Password1');
    await page.fill('input[name="repeatedPassword"]', 'Password1');
    await page.click('input[value="Register"]');
    await expect(page).toHaveURL(/^(?!.*register.htm).*$/);
  });

  test('should not allow submission with empty required fields', async ({ page }) => {
    await page.goto('https://parabank.parasoft.com/parabank/register.htm');
    await page.click('input[value="Register"]');
    await expect(page).toHaveURL('https://parabank.parasoft.com/parabank/register.htm');
    await expect(page.locator('input[name="customer.firstName"]').isVisible());
    await expect(page.locator('input[name="customer.lastName"]').isVisible());
    await expect(page.locator('input[name="customer.address.street"]').isVisible());
    await expect(page.locator('input[name="customer.address.city"]').isVisible());
    await expect(page.locator('input[name="customer.address.state"]').isVisible());
    await expect(page.locator('input[name="customer.address.zipCode"]').isVisible());
    await expect(page.locator('input[name="customer.phoneNumber"]').isVisible());
    await expect(page.locator('input[name="customer.ssn"]').isVisible());
    await expect(page.locator('input[name="customer.username"]').isVisible());
    await expect(page.locator('input[name="customer.password"]').isVisible());
    await expect(page.locator('input[name="repeatedPassword"]').isVisible());
  });
});
